import sys

def inp():
	return sys.stdin.readline().strip()
n = int(input())
x = dict()
mm = -1
for i in range(n):
	(a, b) = map(int, input().split())
	x[a] = b
	mm = max(a, mm)
if 0 in x:
	otv = [1]
else:
	otv = [0]
ma = -1
for i in range(1, mm + 2):
	if i not in x:
		otv.append(otv[i - 1])
		ma = max(ma, otv[i - 1])
	elif i - x[i] - 1 >= 0:
		otv.append(otv[i - 1 - x[i]] + 1)
		ma = max(ma, otv[i - 1 - x[i]] + 1)
	else:
		otv.append(1)
		ma = max(ma, 1)
print(n - ma)
